import{_ as t,a as o,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Delete Customer Profile","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-customer-profile","title":"Delete Customer Profile","description":"Permanently delete the authenticated customer's account. The account is identified by the Bearer token; the body carries nothing.","request":"POST /api/shop/customer-profile-deletes/1821\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\nnull\\n","commonErrors":[{"error":"401 Unauthorized","cause":"The Bearer token is missing, invalid, or already revoked by an earlier delete","solution":"Log the customer in and send the token returned by the login response"},{"error":"401 on every later request","cause":"This is expected — deleting the account revokes all of its tokens","solution":"Clear the stored token client-side and return the shopper to a logged-out state"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customers/delete-customer-profile.md","filePath":"api/rest-api/shop/customers/delete-customer-profile.md","lastUpdated":1787290888000}`),s={name:"api/rest-api/shop/customers/delete-customer-profile.md"};function d(i,e,n,l,h,c){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="delete-customer-profile" tabindex="-1">Delete Customer Profile <a class="header-anchor" href="#delete-customer-profile" aria-label="Permalink to &quot;Delete Customer Profile&quot;">​</a></h1><p>Permanently delete the authenticated customer&#39;s account.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/customer-profile-deletes/{id}</span></span></code></pre></div><p>The <code>{id}</code> is the authenticated customer&#39;s ID. The account acted on is always the one the Bearer token belongs to — an ID belonging to someone else does not delete their account.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token of the customer being deleted</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>Send <code>{}</code>. No field is read — deletion is not password-confirmed at the API level, so treat the call itself as the point of no return and confirm intent in the UI.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>201 Created</code> with a body of <code>null</code>. There is no message payload; the status is the confirmation.</p><h2 id="what-deletion-removes" tabindex="-1">What Deletion Removes <a class="header-anchor" href="#what-deletion-removes" aria-label="Permalink to &quot;What Deletion Removes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Outcome</th></tr></thead><tbody><tr><td>Customer record and profile image</td><td>Deleted.</td></tr><tr><td>Access tokens</td><td>All revoked — every later request with them answers <code>401</code>.</td></tr><tr><td>Saved addresses</td><td>Deleted.</td></tr><tr><td>Cart, wishlist, and compare list</td><td>Deleted.</td></tr><tr><td>Customer notes, social accounts, GDPR requests</td><td>Deleted.</td></tr><tr><td>Purchased downloadable links</td><td>Deleted, so the shopper loses access to files they had bought.</td></tr><tr><td>Orders</td><td>Kept, with the customer link cleared. The name and email captured on the order at checkout remain on the order record.</td></tr><tr><td>Invoices, shipments, refunds</td><td>Kept, attached to those orders.</td></tr><tr><td>Newsletter subscription</td><td>Kept, with the customer link cleared — the address stays subscribed.</td></tr><tr><td>Product reviews</td><td>Kept and still displayed.</td></tr><tr><td>EU withdrawal requests</td><td>Kept, with the customer link cleared.</td></tr></tbody></table><p>The email address becomes free again the moment the record is gone, so the shopper can register a fresh account with it.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Account-closure screen</strong> — call once from a confirmed &quot;delete my account&quot; action, then discard the stored token and route the shopper to the logged-out home page.</li><li><strong>GDPR erasure by the shopper</strong> — this is the self-service counterpart to raising a <code>delete</code> <a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">GDPR request</a>, which instead queues the erasure for an admin to action.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Confirm in the UI, not in the payload</strong> — no password or confirmation field is checked, so the only guard against an accidental deletion is the one you build.</li><li><strong>Warn about downloadable purchases first</strong> — purchased download links are removed with the account, unlike orders, which survive.</li><li><strong>Clear the token immediately after the call</strong> — reusing it produces <code>401</code> on every endpoint, which is easy to misread as an outage.</li><li><strong>Point shoppers who only want to stop emails at the newsletter opt-out</strong> — the subscription survives account deletion, so deleting the account does not unsubscribe them.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Customer Profile</a> — read the authenticated customer&#39;s account details</li><li><a href="/api/rest-api/shop/customers/update-customer-profile.html">Update Customer Profile</a> — patch name, email, phone, and other profile fields</li><li><a href="/api/rest-api/shop/customers/customer-logout.html">Customer Logout</a> — revoke the token used on the request</li></ul>',20)]))}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
